import requests
x=requests.get('https://api.cellxgene.cziscience.com/dp/v1/datasets/index',timeout=120).json()
for d in x:
 diseases={y['label'] for y in d.get('disease',[])}
 tissues={y['label'] for y in d.get('tissue',[])}
 nd=len(d.get('donor_id',[]))
 if 'COVID-19' in diseases and 'normal' in diseases and 'blood' in tissues:
  print(d['id'],d['cell_count'],nd,d['name'])
  if nd<=50:print(' donors',d['donor_id'])
PY"
